// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { FacetValueLabels } from "../../../main/frontend/graph-explorer/facet-value-labels.ts";
import {
  LANGUAGE_FACET_ID,
  intrinsicFacetSparqlFilter,
  normalizedLiteralLanguage,
} from "../../../main/frontend/graph-explorer/graph-filters.ts";
import { mergeTriples } from "../../../main/frontend/graph-explorer/graph-operations.ts";
import { bindingsToTriples } from "../../../main/frontend/graph-explorer/graph-terms.ts";
import {
  isSparqlTerm,
  sparqlFacetValueToken,
  sparqlNodeId,
  sparqlTermFromNodeId,
} from "../../../main/frontend/graph-explorer/rdf-terms.ts";

/**
 * Language tags are ASCII and case-insensitive (BCP 47): they are compared in plain ASCII lower case, as SPARQL's
 * LCASE does, never in the browser's locale. In a Turkish or Azerbaijani locale "I" lowercases to a dotless "ı".
 */
function inTurkishLocale(run) {
  const lower = String.prototype.toLocaleLowerCase;
  const upper = String.prototype.toLocaleUpperCase;
  String.prototype.toLocaleLowerCase = function () {
    return lower.call(this, "tr");
  };
  String.prototype.toLocaleUpperCase = function () {
    return upper.call(this, "tr");
  };
  try {
    assert.equal("I".toLocaleLowerCase(), "ı", "the Turkish case mapping is in effect");
    return run();
  } finally {
    String.prototype.toLocaleLowerCase = lower;
    String.prototype.toLocaleUpperCase = upper;
  }
}

const literal = (language) => ({ type: "literal", value: "Dublin", "xml:lang": language });

test("a literal's identity lowercases its language tag in ASCII in every locale", () => {
  inTurkishLocale(() => {
    for (const tag of ["EN-IE", "en-IE", "EN-ie", "En-Ie"]) {
      const id = sparqlNodeId(literal(tag));
      assert.equal(id, sparqlNodeId(literal("en-ie")), tag);
      const term = sparqlTermFromNodeId(id);
      assert.ok(term && isSparqlTerm(term), `${tag} reads back as a valid term`);
      assert.equal(term["xml:lang"], "en-ie");
      assert.equal(sparqlFacetValueToken(id), '"Dublin"@en-ie');
    }
  });
});

test("identical literals with differently cased tags are one node", () => {
  inTurkishLocale(() => {
    const row = (tag) => ({
      source: { type: "uri", value: "urn:city" },
      predicate: { type: "uri", value: "urn:name" },
      target: literal(tag),
    });
    const graph = mergeTriples({ nodes: [], edges: [], revision: 0 }, bindingsToTriples([row("EN-IE"), row("en-ie"), row("EN-IN")]));
    const languages = graph.nodes.filter((node) => node.kind === "literal").map((node) => sparqlTermFromNodeId(node.id)["xml:lang"]);
    assert.deepEqual(languages.sort(), ["en-ie", "en-in"]);
  });
});

test("the language filter and its SPARQL compare the same ASCII lower case as LCASE", () => {
  inTurkishLocale(() => {
    assert.equal(normalizedLiteralLanguage({ kind: "literal", language: " EN-IN " }), "en-in");
    assert.equal(normalizedLiteralLanguage({ kind: "literal", language: "IT" }), "it");
    const filter = intrinsicFacetSparqlFilter(LANGUAGE_FACET_ID, new Set(["EN-IE", "IT"]));
    assert.match(filter, /LCASE\(LANG\(\?focus\)\) = "en-ie"/);
    assert.match(filter, /LCASE\(LANG\(\?focus\)\) = "it"/);
    assert.doesNotMatch(filter, /ı/);
  });
});

test("value labels pick the preferred language whatever its tag's case", async () => {
  const label = (resource, value, language) => ({
    resource: { type: "uri", value: resource },
    labelProperty: { type: "uri", value: "http://www.w3.org/2000/01/rdf-schema#label" },
    label: { type: "literal", value, ...(language ? { "xml:lang": language } : {}) },
  });
  const rows = [
    label("urn:italy", "Italia", "IT"), label("urn:italy", "Untagged Italy"),
    label("urn:ireland", "Éire", "GA-IE"), label("urn:ireland", "Ireland", "EN"),
  ];
  const execute = async () => ({ results: { bindings: rows } });
  const lower = String.prototype.toLocaleLowerCase;
  String.prototype.toLocaleLowerCase = function () {
    return lower.call(this, "tr");
  };
  const labelled = async (languages) => {
    const labels = new FacetValueLabels({ execute, scope: "default", namespace: "n", languages });
    labels.want(["urn:italy", "urn:ireland"], "shown");
    for (let turn = 0; turn < 200 && labels.pending(); turn++) await new Promise((resolve) => setTimeout(resolve, 1));
    return labels;
  };
  try {
    assert.equal((await labelled(["it"])).label("urn:italy"), "Italia");
    assert.equal((await labelled(["ga"])).label("urn:ireland"), "Éire", "a region subtag still matches");
  } finally {
    String.prototype.toLocaleLowerCase = lower;
  }
});
